/**
 * Rehabify Library resources from the founder's prototype: NHS and hospital pages, videos,
 * Rehabify's own written guides (with Yorùbá, Igbo and Hausa drafts) and red-flag lists.
 *
 * syncSeed copies convex/libraryResourcesSeed.ts (generated by scripts/library-import) into the
 * tables. Items we have built in 3D carry `animationSlug`, so the care team can send the
 * animation instead of the third-party video.
 */
import { v } from "convex/values";
import { internalMutation, mutation, query, type MutationCtx } from "./_generated/server";
import type { Doc } from "./_generated/dataModel";
import { ensureUserRole } from "./auth";
import { libraryAccess } from "./helpers/exerciseAccess";
import { LIBRARY_RESOURCES, LIBRARY_SEED_VERSION, RED_FLAGS } from "./libraryResourcesSeed";

const lang = v.union(v.literal("en"), v.literal("yo"), v.literal("ig"), v.literal("ha"));

async function syncSeed(ctx: MutationCtx) {
  const now = Date.now();
  let created = 0;
  let updated = 0;
  const keys = new Set<string>();
  for (const resource of LIBRARY_RESOURCES) {
    keys.add(resource.key);
    const doc = { ...resource, active: true, seedVersion: LIBRARY_SEED_VERSION, updatedAt: now };
    const existing = await ctx.db
      .query("libraryResources")
      .withIndex("by_key", (q) => q.eq("key", resource.key))
      .first();
    if (existing) {
      await ctx.db.replace(existing._id, doc);
      updated++;
    } else {
      await ctx.db.insert("libraryResources", doc);
      created++;
    }
  }
  // Items dropped from the seed stay in old programmes but leave the library.
  let retired = 0;
  for (const row of await ctx.db.query("libraryResources").collect()) {
    if (row.active && !keys.has(row.key)) {
      await ctx.db.patch(row._id, { active: false, updatedAt: now });
      retired++;
    }
  }
  for (const flags of RED_FLAGS) {
    const doc = { ...flags, seedVersion: LIBRARY_SEED_VERSION };
    const existing = await ctx.db
      .query("libraryRedFlags")
      .withIndex("by_region_lang", (q) => q.eq("region", flags.region).eq("lang", flags.lang))
      .first();
    if (existing) await ctx.db.replace(existing._id, doc);
    else await ctx.db.insert("libraryRedFlags", doc);
  }
  return { created, updated, retired, redFlags: RED_FLAGS.length, version: LIBRARY_SEED_VERSION };
}

/** Admin: load or refresh the library resources from the bundled seed. */
export const syncLibraryResources = mutation({
  args: {},
  handler: async (ctx) => {
    await ensureUserRole(ctx, ["admin"]);
    return await syncSeed(ctx);
  },
});

/** Same, for deploy scripts: `npx convex run libraryResources:syncLibraryResourcesInternal`. */
export const syncLibraryResourcesInternal = internalMutation({
  args: {},
  handler: async (ctx) => syncSeed(ctx),
});

/** List row: everything but the guide text, which getResource returns. */
export function listRow(r: Doc<"libraryResources">) {
  return {
    key: r.key,
    kind: r.kind,
    title: r.title,
    source: r.source,
    url: r.url ?? null,
    youtubeId: r.youtubeId ?? null,
    region: r.region,
    condition: r.condition,
    type: r.type,
    tags: r.tags,
    animationSlug: r.animationSlug ?? null,
    guideLangs: r.guides.map((g) => ({ lang: g.lang, status: g.status })),
  };
}

/** The resource library for the care team and licensees (not patients or Rehabify Learn learners). */
export const listResources = query({
  args: { region: v.optional(v.string()) },
  handler: async (ctx, args) => {
    const access = await libraryAccess(ctx);
    if (!access || access.kind === "patient") return null;
    const rows = args.region
      ? await ctx.db.query("libraryResources").withIndex("by_region", (q) => q.eq("region", args.region!)).collect()
      : await ctx.db.query("libraryResources").collect();
    return rows.filter((r) => r.active).map(listRow).sort((a, b) => a.title.localeCompare(b.title));
  },
});

/** One resource with its written guide in every language we hold. */
export const getResource = query({
  args: { key: v.string() },
  handler: async (ctx, args) => {
    const access = await libraryAccess(ctx);
    if (!access || access.kind === "patient") return null;
    const row = await ctx.db
      .query("libraryResources")
      .withIndex("by_key", (q) => q.eq("key", args.key))
      .first();
    return row ? { ...listRow(row), guides: row.guides } : null;
  },
});

/**
 * Red flags for a body region in the reader's language. Translations that a clinician hasn't
 * reviewed yet fall back to English, so nobody relies on an unchecked safety list.
 */
export const redFlagsFor = query({
  args: { region: v.string(), lang: v.optional(lang) },
  handler: async (ctx, args) => {
    const access = await libraryAccess(ctx);
    if (!access) return null;
    const find = (l: "en" | "yo" | "ig" | "ha", region: string) =>
      ctx.db
        .query("libraryRedFlags")
        .withIndex("by_region_lang", (q) => q.eq("region", region).eq("lang", l))
        .first();
    const wanted = args.lang ?? "en";
    for (const region of [args.region, "general"]) {
      const translated = wanted !== "en" ? await find(wanted, region) : null;
      if (translated?.status === "reviewed") return { region, lang: wanted, items: translated.items };
      const english = await find("en", region);
      if (english) return { region, lang: "en" as const, items: english.items };
    }
    return null;
  },
});
